// Package store -- pricing_catalogue.go
//
// The vendored, pruned copy of litellm's model price list
// (pricing_catalogue.json, regenerated by `make pricing-refresh`) and its
// mapping onto model_pricing rows (ARCHITECTURE.md, Cost estimation >
// Pricing table). The file is embedded in the binary, so the API prices
// calls without a deployment artefact or an outbound request.
package store

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/flightdeckhq/flightdeck/api/internal/modelid"
)

//go:embed pricing_catalogue.json
var catalogueJSON []byte

// Platform families model_pricing rows are keyed by. A call on a
// platform with no row of its own is priced from the direct row.
const (
	platformDirect  = "direct"
	platformBedrock = "bedrock"
	platformVertex  = "vertex"
	platformAzure   = "azure"
	platformFoundry = "foundry"
)

// Row sources, stored in model_pricing.source.
const (
	sourceCatalogue = "catalogue"
	sourceOverride  = "override"
	sourceAlias     = "alias"
)

// perMillion converts litellm's per-token USD rates to the USD per
// million tokens model_pricing stores.
const perMillion = 1_000_000

// PriceRow is one model_pricing row. Rates are USD per million tokens;
// nil pointers are NULL columns (no such rate, or no tier).
type PriceRow struct {
	ModelID            string   `json:"model_id"`
	Platform           string   `json:"platform"`
	Provider           string   `json:"provider"`
	Input              float64  `json:"input"`
	Output             float64  `json:"output"`
	CacheRead          float64  `json:"cache_read"`
	CacheWrite5m       float64  `json:"cache_write_5m"`
	CacheWrite1h       float64  `json:"cache_write_1h"`
	Reasoning          *float64 `json:"reasoning,omitempty"`
	TierThreshold      *int64   `json:"tier_threshold_tokens,omitempty"`
	TierInput          *float64 `json:"tier_input,omitempty"`
	TierOutput         *float64 `json:"tier_output,omitempty"`
	TierCacheRead      *float64 `json:"tier_cache_read,omitempty"`
	TierCacheWrite5m   *float64 `json:"tier_cache_write_5m,omitempty"`
	TierCacheWrite1h   *float64 `json:"tier_cache_write_1h,omitempty"`
	PriorityMultiplier *float64 `json:"priority_multiplier,omitempty"`
	FastMultiplier     *float64 `json:"fast_multiplier,omitempty"`
	Source             string   `json:"source"`
	DeprecatedOn       *string  `json:"deprecated_on,omitempty"`
}

// rowKey identifies a model_pricing row.
type rowKey struct{ model, platform string }

// catalogueFile is the shape pricing_refresh.py writes.
type catalogueFile struct {
	Source    string                    `json:"source"`
	Refreshed string                    `json:"refreshed"`
	Models    map[string]catalogueEntry `json:"models"`
}

// catalogueEntry holds the litellm fields the cost model reads; the
// context-tier rates arrive under keys with the threshold in their name
// and are collected separately.
type catalogueEntry map[string]json.RawMessage

// tierKey matches a context-tier rate: <base field>_above_<N>k_tokens.
var tierKey = regexp.MustCompile(
	`^(input_cost_per_token|output_cost_per_token|cache_read_input_token_cost` +
		`|cache_creation_input_token_cost|cache_creation_input_token_cost_above_1hr)` +
		`_above_(\d+)k_tokens$`,
)

// familyOf maps a litellm provider to the platform family its prices
// apply to; "" for a provider the catalogue should not contain.
func familyOf(litellmProvider string) string {
	switch {
	case litellmProvider == "bedrock" || litellmProvider == "bedrock_converse":
		return platformBedrock
	case strings.HasPrefix(litellmProvider, "vertex_ai"):
		return platformVertex
	case litellmProvider == "azure":
		return platformAzure
	case litellmProvider == "azure_ai":
		return platformFoundry
	case litellmProvider == "anthropic", litellmProvider == "openai", litellmProvider == "gemini",
		litellmProvider == "xai", litellmProvider == "mistral", litellmProvider == "deepseek",
		litellmProvider == "meta_llama":
		return platformDirect
	default:
		return ""
	}
}

func (e catalogueEntry) number(field string) (float64, bool) {
	raw, ok := e[field]
	if !ok {
		return 0, false
	}
	var v float64
	if err := json.Unmarshal(raw, &v); err != nil || v < 0 {
		return 0, false
	}
	return v, true
}

func (e catalogueEntry) text(field string) string {
	var v string
	if raw, ok := e[field]; ok {
		_ = json.Unmarshal(raw, &v)
	}
	return v
}

func ptr[T any](v T) *T { return &v }

// catalogueRows maps the embedded catalogue onto model_pricing rows.
func catalogueRows() ([]PriceRow, error) {
	return parseCatalogue(catalogueJSON)
}

// awsRegion matches an AWS region path segment (us-east-1, ap-northeast-1,
// us-gov-west-1).
var awsRegion = regexp.MustCompile(`^[a-z]{2}(-gov)?-[a-z]+-\d+$`)

// regionSegments are the region path segments litellm uses for Azure and
// Vertex AI keys (azure/eu/gpt-4o, azure/us/...).
var regionSegments = map[string]bool{
	"eu": true, "us": true, "us-gov": true, "apac": true, "jp": true, "au": true, "ca": true,
}

// Key ranks, lowest preferred: a key that names no region carries the
// standard price; a global one is next; a regional one (data-zone or
// region pricing, often at a premium) is used only when nothing else
// prices the model.
const (
	rankStandard = iota
	rankGlobal
	rankRegional
)

// keyRank classifies a raw catalogue key by the region it names, from
// its path segments and from a Bedrock inference-profile prefix.
func keyRank(key string) int {
	rank := rankStandard
	segments := strings.Split(strings.ToLower(key), "/")
	for _, seg := range segments[:len(segments)-1] {
		switch {
		case seg == "global":
			rank = max(rank, rankGlobal)
		case regionSegments[seg] || awsRegion.MatchString(seg):
			rank = rankRegional
		}
	}
	switch modelid.Canonicalize(key).InferenceScope {
	case modelid.ScopeGlobal:
		rank = max(rank, rankGlobal)
	case modelid.ScopeRegional:
		rank = rankRegional
	}
	return rank
}

// parseCatalogue maps a catalogue document onto model_pricing rows, one
// per canonical model id and platform family. Several litellm keys can
// canonicalise to the same row (a Bedrock model and its regional
// inference profiles, an Azure model and its eu / us data-zone keys);
// the best-ranked key wins (see keyRank), then the alphabetically first,
// so the result does not depend on map order.
func parseCatalogue(doc []byte) ([]PriceRow, error) {
	var file catalogueFile
	if err := json.Unmarshal(doc, &file); err != nil {
		return nil, fmt.Errorf("parse pricing catalogue: %w", err)
	}
	keys := make([]string, 0, len(file.Models))
	for k := range file.Models {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	type candidate struct {
		row  PriceRow
		rank int
	}
	chosen := map[rowKey]candidate{}
	for _, key := range keys {
		entry := file.Models[key]
		family := familyOf(entry.text("litellm_provider"))
		if family == "" {
			continue
		}
		c := modelid.Canonicalize(key)
		if c.Model == "" {
			continue
		}
		row, ok := rowFromEntry(c.Model, family, entry)
		if !ok {
			continue
		}
		k := rowKey{row.ModelID, row.Platform}
		rank := keyRank(key)
		if prev, seen := chosen[k]; seen && prev.rank <= rank {
			continue
		}
		chosen[k] = candidate{row: row, rank: rank}
	}
	rows := make([]PriceRow, 0, len(chosen))
	for _, c := range chosen {
		rows = append(rows, c.row)
	}
	sortRows(rows)
	return rows, nil
}

// rowFromEntry builds one row from a catalogue entry; false when the
// entry has no usable input and output rate.
func rowFromEntry(model, family string, e catalogueEntry) (PriceRow, bool) {
	input, okIn := e.number("input_cost_per_token")
	output, okOut := e.number("output_cost_per_token")
	if !okIn {
		return PriceRow{}, false
	}
	if !okOut {
		output = 0 // embedding models have no output rate
	}
	row := PriceRow{
		ModelID:  model,
		Platform: family,
		Provider: modelid.Provider(model),
		Input:    input * perMillion,
		Output:   output * perMillion,
		Source:   sourceCatalogue,
	}
	row.CacheRead = row.Input
	if v, ok := e.number("cache_read_input_token_cost"); ok {
		row.CacheRead = v * perMillion
	}
	row.CacheWrite5m = row.Input
	if v, ok := e.number("cache_creation_input_token_cost"); ok {
		row.CacheWrite5m = v * perMillion
	}
	row.CacheWrite1h = row.CacheWrite5m
	if v, ok := e.number("cache_creation_input_token_cost_above_1hr"); ok {
		row.CacheWrite1h = v * perMillion
	}
	if v, ok := e.number("output_cost_per_reasoning_token"); ok {
		row.Reasoning = ptr(v * perMillion)
	}
	if v, ok := e.number("input_cost_per_token_priority"); ok && input > 0 {
		row.PriorityMultiplier = ptr(v / input)
	}
	if raw, ok := e["provider_specific_entry"]; ok {
		var specific struct {
			Fast *float64 `json:"fast"`
		}
		if json.Unmarshal(raw, &specific) == nil && specific.Fast != nil && *specific.Fast > 0 {
			row.FastMultiplier = ptr(*specific.Fast)
		}
	}
	if d := e.text("deprecation_date"); d != "" {
		if _, err := time.Parse(time.DateOnly, d); err == nil {
			row.DeprecatedOn = ptr(d)
		}
	}
	applyTier(&row, e)
	return row, true
}

// applyTier sets the context tier from the lowest threshold the entry
// prices above; a rate the tier does not list keeps its base value.
func applyTier(row *PriceRow, e catalogueEntry) {
	lowest := int64(0)
	for field := range e {
		m := tierKey.FindStringSubmatch(field)
		if m == nil || m[1] != "input_cost_per_token" {
			continue
		}
		n, err := strconv.ParseInt(m[2], 10, 64)
		if err == nil && (lowest == 0 || n < lowest) {
			lowest = n
		}
	}
	if lowest == 0 {
		return
	}
	suffix := fmt.Sprintf("_above_%dk_tokens", lowest)
	rate := func(field string, base float64) *float64 {
		if v, ok := e.number(field + suffix); ok {
			return ptr(v * perMillion)
		}
		return ptr(base)
	}
	row.TierThreshold = ptr(lowest * 1000)
	row.TierInput = rate("input_cost_per_token", row.Input)
	row.TierOutput = rate("output_cost_per_token", row.Output)
	row.TierCacheRead = rate("cache_read_input_token_cost", row.CacheRead)
	row.TierCacheWrite5m = rate("cache_creation_input_token_cost", row.CacheWrite5m)
	row.TierCacheWrite1h = rate("cache_creation_input_token_cost_above_1hr", row.CacheWrite1h)
}

// sortRows orders rows by model id then platform, so the table content
// and its hash are stable.
func sortRows(rows []PriceRow) {
	sort.Slice(rows, func(i, j int) bool {
		if rows[i].ModelID != rows[j].ModelID {
			return rows[i].ModelID < rows[j].ModelID
		}
		return rows[i].Platform < rows[j].Platform
	})
}
